"""Top 100 Cartoon Series, Top 100 Animated Feature Films, and Top Cartoon Episodes Database.

Curated catalog of greatest Western animation, cartoons, and animated masterpieces
with ratings from IMDb, Rotten Tomatoes, and Letterboxd.
"""

from typing import Dict, List, Any

def calculate_cartoon_cinescore(imdb: float, rt: int, lb: float = 4.0) -> float:
    """Calculates weighted CineScore (0-100) for cartoon media."""
    norm_imdb = (imdb / 10.0) * 100
    norm_rt = float(rt)
    norm_lb = (lb / 5.0) * 100
    return round((norm_imdb * 0.45) + (norm_rt * 0.35) + (norm_lb * 0.20), 1)

