# Generate Master Cartoons DB with CineScore
MASTER_CARTOONS_DB: List[Dict[str, Any]] = []
for idx, c in enumerate(RAW_TOP_CARTOON_SERIES, 1):
    c_copy = dict(c)
    c_copy["id"] = f"cartoon_top100_{idx:03d}"
    c_copy["rank_top100"] = idx
    c_copy["media_type"] = "cartoon_series"
    c_copy["cinescore"] = calculate_cartoon_cinescore(c_copy["imdb_rating"], c_copy["rotten_tomatoes_pct"])
    MASTER_CARTOONS_DB.append(c_copy)
